class Solution:
 def hasAlternatingBits(self,n):
  prev=n&1;n>>=1
  while n:
   bit=n&1
   if bit==prev:return False
   prev=bit;n>>=1
  return True

class Solution:
 def maxAreaOfIsland(self,grid):
  if not grid:return 0
  m,n=len(grid),len(grid[0]);seen=set();best=0
  for r in range(m):
   for c in range(n):
    if grid[r][c] and (r,c) not in seen:
     stack=[(r,c)];seen.add((r,c));area=0
     while stack:
      x,y=stack.pop();area+=1
      for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
       if 0<=a<m and 0<=b<n and grid[a][b] and (a,b) not in seen:seen.add((a,b));stack.append((a,b))
     best=max(best,area)
  return best

class Solution:
 def countBinarySubstrings(self,s):
  prev=0;cur=1;ans=0
  for i in range(1,len(s)):
   if s[i]==s[i-1]:cur+=1
   else:ans+=min(prev,cur);prev=cur;cur=1
  return ans+min(prev,cur)

class Solution:
 def findShortestSubArray(self,nums):
  count={};first={};last={}
  for i,x in enumerate(nums):
   count[x]=count.get(x,0)+1;first.setdefault(x,i);last[x]=i
  degree=max(count.values());return min(last[x]-first[x]+1 for x in count if count[x]==degree)

class Solution:
 def searchBST(self,root,val):
  while root and root.val!=val:root=root.left if val<root.val else root.right
  return root

